<script lang="ts">import type{BubbleAttachmentSide,BubbleVisibility,ConversationSide}from'@fex-design/core/bubble/types';import{bubbleActionsClassName}from'@fex-design/styles/bubble';import{cn}from'@fex/utils';import{getContext,type Snippet}from'svelte';import type{HTMLAttributes}from'svelte/elements';import{bubbleContextKey,type BubbleContextValue}from'./context';interface Props extends HTMLAttributes<HTMLDivElement>{side?:BubbleAttachmentSide;align?:ConversationSide;visibility?:BubbleVisibility;children?:Snippet}let{side='bottom',align:alignProp,visibility='always',class:className,children,...rest}:Props=$props();const context=getContext<BubbleContextValue|undefined>(bubbleContextKey);let align=$derived(alignProp??context?.side()??'start')</script>
<div {...rest} data-slot="bubble-actions" data-side={side} data-align={align} data-visibility={visibility} class={cn(bubbleActionsClassName({side}),className)}>{@render children?.()}</div>
